public class AbstractCommandLineRunner_doRun_TriageGen1Test {

    private TestRunner runner;

    @Mock private Compiler<CompilerOptions> mockCompiler;
    @Mock private CompilerOptions mockOptions;
    @Mock private CommandLineConfig mockConfig;
    @Mock private Result mockResult;
    @Mock private JSSourceFile mockSourceFile;
    @Mock private JSModule mockModule;
    @Mock private Writer mockWriter;
    @Mock private OutputStream mockOutputStream;

    // Concrete implementation for testing abstract class
    private static class TestRunner extends AbstractCommandLineRunner<CompilerOptions, CompilerOptions> {
        private final Compiler<CompilerOptions> compiler;
        private final CompilerOptions options;
        private final CommandLineConfig config;
        private Writer out;

        protected TestRunner(Compiler<CompilerOptions> compiler, CompilerOptions options, CommandLineConfig config) {
            this.compiler = compiler;
            this.options = options;
            this.config = config;
        }

        @Override protected Compiler<CompilerOptions> createCompiler() { return compiler; }
        @Override protected CompilerOptions createOptions() { return options; }
        @Override protected CommandLineConfig getCommandLineConfig() { return config; }
        @Override protected List<JSSourceFile> createExterns() throws java.io.IOException { return Collections.emptyList(); }
        @Override protected List<JSSourceFile> createSourceInputs(List<String> jsFiles) { return Collections.emptyList(); }
        @Override protected List<JSModule> createJsModules(List<String> moduleSpecs, List<String> jsFiles) { return Collections.emptyList(); }
        @Override protected int processResults(Result result, List<JSModule> modules, CompilerOptions options) { return 0; }
        @Override protected void setRunOptions(CompilerOptions options) throws java.io.FlagUsageException, java.io.IOException {}

        // Helper to inject 'out' for testing the Closeable logic
        public void setOut(Writer writer) { this.out = writer; }
        public void setOut(OutputStream os) { this.out = null; /* Logic in doRun handles conversion */ }

        // For testing the 'else if (out instanceof OutputStream)' branch
        public void setOutAsStream(OutputStream os) { 
            // We need to bypass the logic or mock the behavior. 
            // Since 'out' is a field in the runner, we access it via reflection or a setter if available.
            // In this test, we will simulate the flow.
        }
    }

    // Dummy class for FlagUsageException if not accessible
    class FlagUsageException extends Exception {}

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        runner = spy(new TestRunner(mockCompiler, mockOptions, mockConfig));

        // Default config setup
        when(mockConfig.loggingLevel).thenReturn("INFO");
        when(mockConfig.js).thenReturn(Collections.singletonList("file.js"));
        when(mockConfig.module).thenReturn(Collections.emptyList());

        // Default options setup
        when(mockOptions.jsOutputFile).thenReturn("");

        // Mock compiler behavior
        when(mockCompiler.compile(any(), any(), any())).thenReturn(mockResult);
        when(mockCompiler.compileModules(any(), any(), any())).thenReturn(mockResult);
    }

    @Test
    public void testDoRun_StandardCompilation() throws Exception {
        // Setup: No modules, no output file
        when(mockConfig.js).thenReturn(Arrays.asList("input.js"));
        when(mockConfig.module).thenReturn(Collections.emptyList());
        when(mockOptions.jsOutputFile).thenReturn("");

        // Mocking the internal method calls via spy
        doReturn(Collections.singletonList(mockSourceFile)).when(runner).createSourceInputs(any());
        doReturn(0).when(runner).processResults(any(), any(), any());

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockCompiler).compile(any(), any(), any());
    }

    @Test
    public void testDoRun_ModuleCompilation() throws Exception {
        // Setup: Modules present
        when(mockConfig.js).thenReturn(Arrays.asList("input.js"));
        when(mockConfig.module).thenReturn(Arrays.asList("module.js"));
        when(mockOptions.jsOutputFile).thenReturn("");

        doReturn(Collections.singletonList(mockModule)).when(runner).createJsModules(any(), any());
        doReturn(0).when(runner).processResults(any(), any(), any());

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockCompiler).compileModules(any(), any(), any());
    }

    @Test
    public void testDoRun_WriteToFile() throws Exception {
        // Setup: Output file provided
        when(mockConfig.js).thenReturn(Arrays.asList("input.js"));
        when(mockConfig.module).thenReturn(Collections.emptyList());
        when(mockOptions.jsOutputFile).thenReturn("output.js");

        // Use a real Closeable writer to test the close() branch
        Writer mockWriterCloseable = mock(Writer.class, withSettings().extraInterfaces(Closeable.class));
        doReturn(mockWriterCloseable).when(runner).fileNameToOutputWriter("output.js");

        doReturn(0).when(runner).processResults(any(), any(), any());

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockWriterCloseable).close();
    }

    @Test
    public void testDoRun_OutputStreamBranch() throws Exception {
        // Setup: out is an OutputStream
        when(mockConfig.js).thenReturn(Arrays.asList("input.js"));
        when(mockConfig.module).thenReturn(Collections.emptyList());
        when(mockOptions.jsOutputFile).thenReturn("");

        // Manually inject an OutputStream into the runner's 'out' field via reflection or simulated flow
        // Since we can't easily change the protected 'out' field type in the stub without reflection, 
        // we mock the behavior of the streamToOutputWriter call.

        OutputStream mockOs = mock(OutputStream.class, withSettings().extraInterfaces(Closeable.class));
        // We need the runner to have 'out' as an OutputStream. 
        // In the real class, 'out' is likely a protected field.
        // We simulate the 'else if (out instanceof OutputStream)' logic.

        // This test requires the runner's 'out' to be an OutputStream. 
        // For the sake of this unit test, we assume we can control the state of the runner.
        // We will use a subclass to expose the field or use reflection.
        java.lang.reflect.Field outField = AbstractCommandLineRunner.class.getDeclaredField("out");
        outField.setAccessible(true);
        outField.set(runner, mockOs);

        doReturn(mock(Writer.class)).when(runner).streamToOutputWriter(any());
        doReturn(0).when(runner).processResults(any(), any(), any());

        int result = runner.doRun();

        assertEquals(0, result);
        verify(mockOs).close();
    }
}
